// AUTO-GENERATED from "Rural Property Sale Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms and conditions under which Seventh Sky will provide Rural Property Sale Services to assist the Client in preparing, marketing, promoting, negotiating and coordinating the sale of the property described in this Agreement.</p><p style=\"margin:6px 0;\">The Agreement establishes the rights and responsibilities of both Parties in relation to property assessment, marketing, buyer management, documentation coordination, settlement support and other agreed sale services.</p><p style=\"margin:6px 0;\">The specific Services, pricing and engagement scope applicable to each transaction shall be confirmed in the approved Quotation, Work Order or Property Sale Schedule.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement commences on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">the property sale has been completed;</li><li style=\"margin:2px 0;\">the Agreement is terminated in accordance with its terms; or</li><li style=\"margin:2px 0;\">both Parties otherwise agree in writing.</li></ul><p style=\"margin:6px 0;\">Where the Seller appoints Seventh Sky on an exclusive basis, the exclusive engagement period shall be specified in the approved Quotation or Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">Depending on the selected engagement, Seventh Sky may provide one or more of the following Services.</p><p style=\"margin:6px 0;\">Only the Services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Assessment &amp; Sale Planning</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Property Assessment</li><li style=\"margin:2px 0;\">☐ Rural Market Assessment</li><li style=\"margin:2px 0;\">☐ Property Pricing Guidance</li><li style=\"margin:2px 0;\">☐ Sale Strategy Planning</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Preparation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Property Presentation Advice</li><li style=\"margin:2px 0;\">☐ Land Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Boundary Verification Coordination</li><li style=\"margin:2px 0;\">☐ Cleaning Coordination</li><li style=\"margin:2px 0;\">☐ Property Improvement Recommendations</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Marketing &amp; Promotion</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Professional Photography Coordination</li><li style=\"margin:2px 0;\">☐ Videography Coordination</li><li style=\"margin:2px 0;\">☐ Drone Photography Coordination</li><li style=\"margin:2px 0;\">☐ Online Marketing</li><li style=\"margin:2px 0;\">☐ Social Media Promotion</li><li style=\"margin:2px 0;\">☐ Buyer Database Promotion</li><li style=\"margin:2px 0;\">☐ Property Signboard Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Buyer &amp; Sale Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Buyer Enquiry Management</li><li style=\"margin:2px 0;\">☐ Property Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Buyer Communication</li><li style=\"margin:2px 0;\">☐ Negotiation Support</li><li style=\"margin:2px 0;\">☐ Offer Coordination</li><li style=\"margin:2px 0;\">☐ Sale Agreement Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Documentation &amp; Professional Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Ownership Verification Coordination</li><li style=\"margin:2px 0;\">☐ Khatian Review Coordination</li><li style=\"margin:2px 0;\">☐ Dag Review Coordination</li><li style=\"margin:2px 0;\">☐ Mutation Review Coordination</li><li style=\"margin:2px 0;\">☐ Survey Coordination</li><li style=\"margin:2px 0;\">☐ Legal Coordination</li><li style=\"margin:2px 0;\">☐ Registration Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Property Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Agricultural Assessment Coordination</li><li style=\"margin:2px 0;\">☐ Environmental Assessment Coordination</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional Services may be included by written agreement.</p>"],
  ["PROPERTY DETAILS", "<p style=\"margin:6px 0;\">The property to which this Agreement relates shall be recorded in Schedule B or the approved Property Sale Schedule.</p><p style=\"margin:6px 0;\">The property information may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Property Address;</li><li style=\"margin:2px 0;\">District;</li><li style=\"margin:2px 0;\">Upazila;</li><li style=\"margin:2px 0;\">Union;</li><li style=\"margin:2px 0;\">Village;</li><li style=\"margin:2px 0;\">Mouza;</li><li style=\"margin:2px 0;\">Khatian Number;</li><li style=\"margin:2px 0;\">Dag Number;</li><li style=\"margin:2px 0;\">Land Area;</li><li style=\"margin:2px 0;\">Property Type;</li><li style=\"margin:2px 0;\">Ownership Status;</li><li style=\"margin:2px 0;\">Agreed Listing Price;</li><li style=\"margin:2px 0;\">Exclusive or Non-Exclusive Appointment; and</li><li style=\"margin:2px 0;\">Any special instructions agreed by the Parties.</li></ul><p style=\"margin:6px 0;\">Where any inconsistency exists between this Agreement and the approved Work Order or Property Sale Schedule, the approved Work Order or Property Sale Schedule shall prevail for that transaction.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Seller agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate, complete and lawful information relating to the property and its ownership;</li><li style=\"margin:2px 0;\">provide all documents reasonably required to perform the agreed Services;</li><li style=\"margin:2px 0;\">confirm they have the legal authority to sell or market the property;</li><li style=\"margin:2px 0;\">promptly disclose any ownership disputes, mortgages, court proceedings, restrictions or other matters affecting the property;</li><li style=\"margin:2px 0;\">cooperate with inspections, marketing activities and genuine buyer enquiries;</li><li style=\"margin:2px 0;\">provide reasonable access to the property where required;</li><li style=\"margin:2px 0;\">pay all agreed Service Fees and approved third-party costs in accordance with this Agreement;</li><li style=\"margin:2px 0;\">obtain independent legal, taxation, financial, surveying or valuation advice where appropriate; and</li><li style=\"margin:2px 0;\">promptly notify Seventh Sky of any material changes affecting the property or the proposed sale.</li></ul><p style=\"margin:6px 0;\">The Seller remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the accuracy and legality of all information and documents provided;</li><li style=\"margin:2px 0;\">obtaining all required approvals for the sale;</li><li style=\"margin:2px 0;\">complying with applicable laws and regulations; and</li><li style=\"margin:2px 0;\">making the final decision whether to accept or reject any offer.</li></ul>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide the agreed Services with reasonable care, skill and professional diligence;</li><li style=\"margin:2px 0;\">assist with property assessment and sale planning;</li><li style=\"margin:2px 0;\">coordinate marketing and promotional activities included within the agreed scope;</li><li style=\"margin:2px 0;\">manage buyer enquiries and inspection arrangements;</li><li style=\"margin:2px 0;\">assist with negotiations where requested;</li><li style=\"margin:2px 0;\">coordinate with lawyers, surveyors, valuers and other approved professionals where required;</li><li style=\"margin:2px 0;\">keep the Seller reasonably informed of significant developments throughout the sale process; and</li><li style=\"margin:2px 0;\">coordinate settlement activities where included within the agreed Services.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts as a Rural Property Sale Service Provider and Coordinator and does not act as the purchaser, legal adviser, surveyor, valuer, engineer or financial adviser.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before commencing the Services, Seventh Sky may issue a Quotation or Work Order specifying:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services;</li><li style=\"margin:2px 0;\">engagement type (exclusive or non-exclusive);</li><li style=\"margin:2px 0;\">Service Fees;</li><li style=\"margin:2px 0;\">sales commission (where applicable);</li><li style=\"margin:2px 0;\">marketing budget (where applicable);</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected project timeframe; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Additional Services requested after commencement may require a revised Quotation, Work Order or approved variation before work proceeds.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The Service Fees payable under this Agreement shall be specified in the approved Quotation, Work Order or Property Sale Schedule.</p><p style=\"margin:6px 0;\">Depending on the agreed engagement, the Service Fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Initial Consultation Fee;</li><li style=\"margin:2px 0;\">Property Assessment &amp; Sale Strategy Fee;</li><li style=\"margin:2px 0;\">Marketing &amp; Promotion Fee;</li><li style=\"margin:2px 0;\">Buyer Management Fee;</li><li style=\"margin:2px 0;\">Negotiation Support Fee;</li><li style=\"margin:2px 0;\">Documentation &amp; Settlement Coordination Fee;</li><li style=\"margin:2px 0;\">Sales Commission (where applicable);</li><li style=\"margin:2px 0;\">Approved Third-Party Costs; and</li><li style=\"margin:2px 0;\">Additional Services requested by the Client.</li></ul><p style=\"margin:6px 0;\">The Seller agrees to pay all agreed Service Fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government charges, registration fees, stamp duty, taxes, legal fees, valuation fees, survey fees and other third-party costs remain the responsibility of the Seller unless otherwise agreed in writing.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Professional Service Fees</p><p style=\"margin:6px 0;\">Professional Service Fees are payable in accordance with the approved Quotation, Work Order or Property Sale Schedule.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Sales Commission</p><p style=\"margin:6px 0;\">Where a Sales Commission has been agreed, it shall become payable upon successful completion of the property sale or as otherwise specified in the approved engagement documents.</p><p style=\"margin:6px 0;\">Third-Party Costs</p><p style=\"margin:6px 0;\">Approved third-party expenses, including marketing, photography, legal, valuation, survey and other specialist services, shall be payable by the Seller.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension of the Services until outstanding amounts have been paid.</p>"],
  ["PROPERTY SALE SERVICES", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to market and coordinate the sale of the Client's rural property in accordance with the agreed scope of Services.</p><p style=\"margin:6px 0;\">Depending on the selected Service Package, the Services may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property assessment and sale planning;</li><li style=\"margin:2px 0;\">property marketing and promotion;</li><li style=\"margin:2px 0;\">buyer enquiry management;</li><li style=\"margin:2px 0;\">property inspection coordination;</li><li style=\"margin:2px 0;\">offer management;</li><li style=\"margin:2px 0;\">negotiation support;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination; and</li><li style=\"margin:2px 0;\">post-sale support Services.</li></ul><p style=\"margin:6px 0;\">The Seller acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property values may change due to market conditions;</li><li style=\"margin:2px 0;\">buyer interest cannot be guaranteed;</li><li style=\"margin:2px 0;\">Seventh Sky does not guarantee the sale of the property within a particular timeframe or at a particular price; and</li><li style=\"margin:2px 0;\">the final decision to accept or reject any offer remains solely with the Seller.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order where applicable.</p><p style=\"margin:6px 0;\">Project timeframes may vary depending on factors including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">market conditions;</li><li style=\"margin:2px 0;\">buyer demand;</li><li style=\"margin:2px 0;\">property condition;</li><li style=\"margin:2px 0;\">Seller instructions;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">government approvals;</li><li style=\"margin:2px 0;\">registration processes;</li><li style=\"margin:2px 0;\">weather conditions affecting inspections;</li><li style=\"margin:2px 0;\">availability of third-party professionals; and</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Seller reasonably informed and provide revised estimated timeframes where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">The Seller may request changes to the agreed scope of Services at any time.</p><p style=\"margin:6px 0;\">Additional Services may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional marketing campaigns;</li><li style=\"margin:2px 0;\">professional photography or videography;</li><li style=\"margin:2px 0;\">drone photography;</li><li style=\"margin:2px 0;\">additional inspections;</li><li style=\"margin:2px 0;\">property presentation assistance;</li><li style=\"margin:2px 0;\">valuation coordination;</li><li style=\"margin:2px 0;\">survey coordination;</li><li style=\"margin:2px 0;\">legal coordination;</li><li style=\"margin:2px 0;\">environmental or agricultural assessment coordination; or</li><li style=\"margin:2px 0;\">any other Services requested by the Seller.</li></ul><p style=\"margin:6px 0;\">Where a variation affects the Service Fees, project scope or timeframe, Seventh Sky will provide a revised Quotation, Work Order or variation for approval before proceeding.</p>"],
  ["PROPERTY SALE COORDINATION & THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where required, Seventh Sky may coordinate independent third-party professionals to support the sale of the property.</p><p style=\"margin:6px 0;\">These may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">lawyers;</li><li style=\"margin:2px 0;\">surveyors;</li><li style=\"margin:2px 0;\">valuers;</li><li style=\"margin:2px 0;\">engineers;</li><li style=\"margin:2px 0;\">photographers;</li><li style=\"margin:2px 0;\">marketing agencies;</li><li style=\"margin:2px 0;\">financial institutions;</li><li style=\"margin:2px 0;\">government authorities; and</li><li style=\"margin:2px 0;\">other specialist service providers.</li></ul><p style=\"margin:6px 0;\">The Seller acknowledges that these providers operate independently and remain responsible for their own professional advice and services.</p><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts solely as the coordinator of these Services and is not responsible for the professional advice, reports or decisions of any independent third-party provider.</p>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be deemed complete when Seventh Sky has substantially delivered the Services specified in the accepted Quotation, Work Order or Property Sale Schedule.</p><p style=\"margin:6px 0;\">Depending on the agreed scope, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property assessment completed;</li><li style=\"margin:2px 0;\">marketing activities completed;</li><li style=\"margin:2px 0;\">buyer enquiries managed;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations facilitated;</li><li style=\"margin:2px 0;\">documentation coordinated;</li><li style=\"margin:2px 0;\">settlement support completed; or</li><li style=\"margin:2px 0;\">other agreed Services completed.</li></ul><p style=\"margin:6px 0;\">Where the Seller requests additional Services after completion, those Services shall be treated as a separate engagement or approved variation under this Agreement.</p>"],
  ["CLIENT COMPLAINTS", "<p style=\"margin:6px 0;\">If the Seller is dissatisfied with any aspect of the Services, the Seller should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge receipt of the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">communicate with the Seller throughout the review process;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue where appropriate; and</li><li style=\"margin:2px 0;\">advise the Seller of the outcome.</li></ul><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">Seventh Sky will perform the agreed Services with reasonable care, skill and professional diligence.</p><p style=\"margin:6px 0;\">The Seller acknowledges that Seventh Sky acts as a Rural Property Sale Service Provider and Coordinator and does not provide legal, financial, taxation, surveying, engineering, valuation or investment advice.</p><p style=\"margin:6px 0;\">The Seller remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the accuracy, authenticity and legality of all information and documents provided;</li><li style=\"margin:2px 0;\">confirming lawful ownership and authority to sell the property;</li><li style=\"margin:2px 0;\">obtaining independent professional advice where appropriate; and</li><li style=\"margin:2px 0;\">making all final decisions relating to the sale of the property.</li></ul><p style=\"margin:6px 0;\">Seventh Sky is not responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">forged, false or misleading documents supplied by the Seller;</li><li style=\"margin:2px 0;\">ownership disputes, succession disputes or boundary disputes;</li><li style=\"margin:2px 0;\">undisclosed mortgages, encumbrances or court proceedings;</li><li style=\"margin:2px 0;\">incorrect information supplied by the Seller;</li><li style=\"margin:2px 0;\">decisions made by the Seller or prospective buyers; or</li><li style=\"margin:2px 0;\">professional advice provided by independent third-party service providers.</li></ul>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">To the maximum extent permitted by law, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">changes in market conditions or property values;</li><li style=\"margin:2px 0;\">failure to achieve a particular sale price;</li><li style=\"margin:2px 0;\">inability to secure a purchaser;</li><li style=\"margin:2px 0;\">delays caused by the Seller, buyers, government authorities or third-party professionals;</li><li style=\"margin:2px 0;\">registration delays;</li><li style=\"margin:2px 0;\">property defects or undisclosed legal issues;</li><li style=\"margin:2px 0;\">advice provided by independent third-party professionals; or</li><li style=\"margin:2px 0;\">any indirect, incidental or consequential loss.</li></ul><p style=\"margin:6px 0;\">Where liability cannot legally be excluded, Seventh Sky's total liability shall not exceed the Professional Service Fees paid by the Seller for the Services giving rise to the claim.</p><p style=\"margin:6px 0;\">Nothing in this clause excludes liability that cannot legally be excluded under applicable law.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Both Parties agree to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Seventh Sky may collect, use and disclose information only for the purpose of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the agreed Services;</li><li style=\"margin:2px 0;\">marketing and coordinating the sale of the property;</li><li style=\"margin:2px 0;\">communicating with buyers and approved third-party professionals;</li><li style=\"margin:2px 0;\">complying with legal obligations; and</li><li style=\"margin:2px 0;\">managing its business operations.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failure to perform its obligations where caused by events beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">floods;</li><li style=\"margin:2px 0;\">fire;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">utility failures;</li><li style=\"margin:2px 0;\">civil unrest; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["CLIENT ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Seller acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have read and understood this Agreement;</li><li style=\"margin:2px 0;\">all information and documents provided to Seventh Sky are true, accurate and complete to the best of their knowledge;</li><li style=\"margin:2px 0;\">they have the lawful authority to market and sell the property;</li><li style=\"margin:2px 0;\">Seventh Sky provides Rural Property Sale Services only and does not guarantee the successful sale of the property or the achievement of any particular sale price;</li><li style=\"margin:2px 0;\">the final decision to accept or reject any offer remains solely with the Seller;</li><li style=\"margin:2px 0;\">independent legal, taxation, financial, surveying, valuation and other professional advice should be obtained where appropriate;</li><li style=\"margin:2px 0;\">independent third-party professionals remain responsible for their own advice and services;</li><li style=\"margin:2px 0;\">all agreed Service Fees, Sales Commission (where applicable) and approved third-party costs remain payable in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">they have had the opportunity to obtain independent legal advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension of Services</p><p style=\"margin:6px 0;\">Seventh Sky may suspend all or part of the Services where the Seller:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">fails to pay any outstanding amount in accordance with this Agreement;</li><li style=\"margin:2px 0;\">provides false, misleading or incomplete information;</li><li style=\"margin:2px 0;\">fails to provide information or instructions reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">requests Seventh Sky to undertake any unlawful activity; or</li><li style=\"margin:2px 0;\">commits a material breach of this Agreement.</li></ul><p style=\"margin:6px 0;\">Where reasonably practicable, Seventh Sky will notify the Seller before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing written notice to the other Party.</p><p style=\"margin:6px 0;\">Where the Seller has appointed Seventh Sky on an exclusive engagement basis, the agreed exclusive engagement period shall remain subject to the terms of this Agreement and the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Seller:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">repeatedly fails to pay agreed Service Fees;</li><li style=\"margin:2px 0;\">engages in fraudulent or unlawful conduct;</li><li style=\"margin:2px 0;\">intentionally circumvents Seventh Sky in breach of this Agreement; or</li><li style=\"margin:2px 0;\">otherwise acts in a manner that makes continuation of the Services unreasonable.</li></ul><p style=\"margin:6px 0;\">Upon termination:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Professional Service Fees for work already completed remain payable;</li><li style=\"margin:2px 0;\">approved Sales Commission (where applicable) remains payable where entitlement has arisen under this Agreement;</li><li style=\"margin:2px 0;\">approved third-party costs remain payable;</li><li style=\"margin:2px 0;\">obligations intended to survive termination shall continue to apply; and</li><li style=\"margin:2px 0;\">termination does not affect any rights or obligations accrued before the termination date.</li></ul>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Seller acknowledges that Seventh Sky invests considerable time, resources and expertise in assessing, marketing and promoting rural properties, sourcing buyers and coordinating the sale process.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a prospective buyer, purchaser, investor or other sale opportunity, the Seller agrees not to intentionally bypass Seventh Sky to avoid payment of the agreed Professional Service Fees or Sales Commission.</p><p style=\"margin:6px 0;\">This obligation applies during the term of this Agreement and for twenty-four (24) months following the introduction of the relevant buyer or purchaser.</p><p style=\"margin:6px 0;\">This clause does not prevent the Seller from independently selling the property where no protected introduction by Seventh Sky is involved, unless an exclusive engagement has been agreed in writing.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order, Property Sale Schedule and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment to this Agreement must be made in writing and accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision shall not constitute a waiver of that provision;</li><li style=\"margin:2px 0;\">if any provision is found to be invalid or unenforceable, the remaining provisions shall remain in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, registered post, courier or email.</li></ul>"],
  ["GOVERNING LAW", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to use reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">Where a dispute cannot be resolved through negotiation, either Party may refer the matter to the competent courts of Bangladesh.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal advice;</li><li style=\"margin:2px 0;\">agree to be bound by the terms of this Agreement; and</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, each of which shall be deemed an original.</p>"],
];
